import{_ as i,l as o,o as e,c as s,v as t,p as l,x as n,d,i as h,S as E}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"最小二乘蒙特卡洛 LSM","description":"","frontmatter":{"title":"最小二乘蒙特卡洛 LSM","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/lsm-american.md","filePath":"quant/lsm-american.md","lastUpdated":1789023840000}'),m={name:"quant/lsm-american.md"};function c(p,a,B,S,_,u){const r=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="最小二乘蒙特卡洛-lsm" tabindex="-1">最小二乘蒙特卡洛 LSM <a class="header-anchor" href="#最小二乘蒙特卡洛-lsm" aria-label="Permalink to &quot;最小二乘蒙特卡洛 LSM&quot;">​</a></h1><div class="epigraph"><p>把续持算子投影到有限基上，用路径截面的最小二乘代替条件期望，美式定价就变成带执行判断的动态规划；偏差来自子空间与样本，而不是来自少抽了几条欧式路径。</p><footer>—— Longstaff and Schwartz, Review of Financial Studies, 2001；Tsitsiklis and Van Roy, IEEE Transactions on Neural Networks, 1999；Clément, Lamberton and Protter, Finance and Stochastics, 2002</footer></div><p><a href="/quant/longstaff-schwartz">Longstaff–Schwartz</a> 给出可落地的路径现金流算法。<a href="/quant/american-exercise">提前行权</a> 写经济与自由边界。本篇把 LSM 当成一类数值方法：条件期望的线性投影、两种价值迭代、基函数与过拟合、下界/上界，以及和欧式 <a href="/quant/mc-pricing">蒙特卡洛</a> 完全不同的误差账本。它服务的是百慕大与高维美式；一维网格仍应走 <a href="/quant/binomial-tree">树</a> 或 <a href="/quant/option-pde">PDE</a>。名字里的「最小二乘」是投影的计算手段，不是普通回归预测收益。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>离散行权日上，续持 \\(C_k(x)=\\mathbb{E}[D_{k+1}V_{k+1}\\mid X_{t_k}=x]\\)。\\(V_{k+1}=\\max(g,C_{k+1})\\) 使算子非线性。函数逼近选一个有限维子空间 \\(\\mathcal{H}=\\mathrm{span}\\{\\psi_1,\\ldots,\\psi_J\\}\\)，用 \\(\\Pi_{\\mathcal{H}}C_k\\) 代替 \\(C_k\\)。问题是：投影之后，下一期代入的是投影值还是真实后续现金流；以及当 \\(\\Pi_{\\mathcal{H}}\\) 换成样本 OLS 时，价格以什么方式收敛。</p><p>两条经典迭代。Tsitsiklis–Van Roy（TVR）让 \\(\\hat V_k=\\max(g,\\hat\\theta_k\\cdot\\psi)\\)，并把 \\(\\hat V_k\\) 贴现后当作下一期回归的响应——价值函数在基上闭环，像拟合值动态规划。Longstaff–Schwartz（LS）只用 \\(\\hat\\theta\\cdot\\psi\\) 做是否执行的分类，响应始终是路径上按该规则实现的现金流。TVR 把逼近误差写进价值，可高可低；LS 的价格对应一个可模拟的停时，便于谈下界。LSM 一词在工程里常混指二者，实现前必须写明闭环的是价值还是现金流。</p><h3 id="投影误差不是蒙特卡洛方差" tabindex="-1">投影误差不是蒙特卡洛方差 <a class="header-anchor" href="#投影误差不是蒙特卡洛方差" aria-label="Permalink to &quot;投影误差不是蒙特卡洛方差&quot;">​</a></h3><p>欧式 MC 的误差主要是 \\(\\mathrm{Var}(Y)/N\\) 与时间离散。LSM 在此之外还有：\\(\\mathcal{H}\\) 不能逼近真 \\(C\\)（逼近偏差）、OLS 的有限 \\(N\\) 噪声（估计偏差/方差）、行权日太稀（百慕大相对连续美式）、以及同一路径样本内评估。加大 \\(N\\) 而不改基，只能压估计噪声，压不掉子空间偏差。这与「再加两个数量级路径，美式价格就会贴住 PDE」的直觉相反。报告 LSM 价格必须同时报告 \\(J\\)、\\(M\\)、\\(N\\) 与是否独立评估，否则无法复核。</p><p><span class="marginnote">基函数选错时，加密路径会让错误规则被估得更「确定」，价格稳定在错误的数上。稳定不等于收敛到真值。应用一维看跌对树做对照，再把同一套基搬到高维，是最低限度的健全性检查。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>共同骨架：模拟路径 → 到期赋值 → 倒推回归 → 执行判断。差异在响应变量与是否改写现金流，见上。基的选择按结构来：单资产多项式或 Laguerre；随机波动把 \\(v\\) 放进 \\(\\psi\\)；篮子用主成分或价格的对称多项式；可转债加入信用强度或转换价值。正则化（Ridge、截断 SVD）在 \\(J\\) 相对实值路径数偏大时比盲目加阶更有用。只回归实值路径是把 \\(\\mathcal{H}\\) 的预算花在自由边界附近；深度虚值美式看跌的价值接近欧式，执行信息本来就少。</p><p>独立评估：路径集 \\(A\\) 估 \\(\\hat\\theta_{1:M}\\)，路径集 \\(B\\) 只执行不回归，平均贴现支付。这给出对应该规则的无偏价格（相对规则而言），标准误按欧式方式报。上界用 Andersen–Broadie：对偶鞅由嵌套模拟估续持，成本高，通常只在基准产品上跑，不作为每日生产。实践中用加大 \\(J\\) 与 \\(N\\) 看下界是否抬升、是否饱和，当作「可能还早执行」的诊断，而不是证明最优。</p><h3 id="过拟合、交叉项与状态缺失" tabindex="-1">过拟合、交叉项与状态缺失 <a class="header-anchor" href="#过拟合、交叉项与状态缺失" aria-label="Permalink to &quot;过拟合、交叉项与状态缺失&quot;">​</a></h3><p>多项式张量积在 \\(d\\) 维上项数为 \\(O(J^d)\\)。路径数必须覆盖系数，否则 OLS 在样本内把噪声当续持，分类器乱跳。优先低阶主效应加少数经济上有意义的交叉（如 \\(S\\cdot v\\) 的杠杆），而不是完整次数 \\(p\\) 的张量。状态缺失比过拟合更致命：亚式漏掉平均，停时在错误的一维流形上做，偏差是模型错误。检查方法是：在已知应永不执行的无股利看涨上，LSM 应给出与欧式 MC 一致的价格；系统性提前执行说明 \\(g\\gt \\hat C\\) 被噪声触发，应减 \\(J\\)、加 \\(N\\)、或提高实值阈值。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>动态规划的 Bellman 算子在真条件期望下收缩（折现）。换成投影后，TVR 是投影 Bellman 的不动点，LS 是「投影只用于贪婪策略、价值沿策略累积」。LS 的下界来自：任意停时的期望不超过本质确界；OLS 策略是某停时（在独立评估时严格如此）。TVR 没有这条免费的不等式。Clément–Lamberton–Protter 证明：先 \\(N\\to\\infty\\) 再让基足够丰富，LS 价格趋向百慕大真值；次序不能反——先把 \\(J\\) 加到接近 \\(N\\)，再谈极限没有意义。</p><p>与网格比：PDE/树在离散化后解的是该网格上的<strong>全局</strong>最优（投影或罚函数意义下），没有策略回归这一层；维数一高网格先死。LSM 把维数代价从节点指数换成基函数与路径。这不是方差缩减：它改变的是可计算的策略集。欧式产品上跑 LSM 等于浪费：没有执行决策，回归无对象。</p><p><span class="marginnote">对偶上界与下界夹住真值，是生产上唯一能报「误差条」的方式，且上界贵。只报一个 LSM 下界、把 MC 标准误当成总误差，会系统性低估——标准误不含子空间偏差。</span></p>',18)),(e(),l(E,null,{default:n(()=>[h(r,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20Bell%5B%22%E7%BB%AD%E6%8C%81%20%3D%20%E6%9D%A1%E4%BB%B6%E6%9C%9F%E6%9C%9B%22%5D%20--%3E%20Proj%5B%22%E6%8A%95%E5%BD%B1%E5%88%B0%20span%20%CF%88%22%5D%0A%20%20Proj%20--%3E%20TVR%5B%22TVR%3A%20%E6%8B%9F%E5%90%88%E5%80%BC%E5%BD%93%E4%BD%9C%20V%20%E5%80%92%E6%8E%A8%22%5D%0A%20%20Proj%20--%3E%20LS%5B%22LS%3A%20%E6%8B%9F%E5%90%88%E5%8F%AA%E5%81%9A%E6%89%A7%E8%A1%8C%E5%88%86%E7%B1%BB%22%5D%0A%20%20TVR%20--%3E%20Bias%5B%22%E9%80%BC%E8%BF%91%E5%81%8F%E5%B7%AE%E5%8F%AF%E6%AD%A3%E5%8F%AF%E8%B4%9F%22%5D%0A%20%20LS%20--%3E%20Low%5B%22%E7%8B%AC%E7%AB%8B%E8%AF%84%E4%BC%B0%20%E2%86%92%20%E4%B8%8B%E7%95%8C%22%5D%0A%20%20Low%20--%3E%20Dual%5B%22%E5%B5%8C%E5%A5%97%E5%AF%B9%E5%81%B6%20%E2%86%92%20%E4%B8%8A%E7%95%8C%22%5D%0A%20%20Dual%20--%3E%20Gap%5B%22%E5%A4%B9%E9%80%BC%E7%9C%9F%E5%80%BC%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="随机贴现、美式亚式与双方停时" tabindex="-1">随机贴现、美式亚式与双方停时 <a class="header-anchor" href="#随机贴现、美式亚式与双方停时" aria-label="Permalink to &quot;随机贴现、美式亚式与双方停时&quot;">​</a></h3><p>利率随机或外汇quanto，贴现因子是路径泛函，\\(Y\\) 必须用累积随机贴现，或把债券价格纳入 \\(X\\)。美式亚式的状态是 \\((S,A)\\)，基要同时依赖二者。可赎回、可转换是发行人和持有人双方停时，LSM 要扩展为交替决策或在联合约束下回归，不能单边套用看跌代码。雇员期权加流失率：流失是外生跳，执行可行集随归属变化，基与可行标志要一起进回归。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>LSM 不消除 Euler 弱偏差：离散 SDE 错了，最优停时是错误过程上的最优。连续障碍加美式，观察偏差与策略偏差叠加。拟随机数在不连续执行指示下优势下降，平滑或用条件期望（给定不执行的桥）更有用。<a href="/quant/cv-european">控制变量</a> 可加在最终支付上，降的是评估方差，不降策略偏差。</p><p>不要把 LSM 当欧式引擎的「升级」；不要用样本内价格报四位小数；不要在一维香草上用百万路径去对标 PDE 却不报基函数。引用时应分开：算法原形 LS 2001 / TVR 1999，收敛 CLP 2002，对偶 Andersen–Broadie 2004。</p><p><span class="marginnote">Glasserman 的《Monte Carlo Methods in Financial Engineering》把美式模拟写成专章，强调策略偏差与欧式方差是不同对象。实现对照原文时，先核对现金流是否改写，再讨论 Laguerre 的项数。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LSM 用有限基上的最小二乘代替续持条件期望；TVR 闭环价值，LS 闭环停时现金流。</li><li>误差 = 子空间 + 有限样本 + 行权日离散 + 评估方式；加大 \\(N\\) 不能替代选基。</li><li>独立评估给出对应规则的下界；上界需对偶，MC 标准误不是总误差。</li><li>状态必须充分；过拟合与张量积爆炸是高维的主要工程风险。</li><li>一维香草用网格；LSM 的理由是维数与复杂可行集。</li><li>出处：Longstaff and Schwartz, <em>RFS</em>, 2001；Tsitsiklis and Van Roy, 1999；Clément, Lamberton and Protter, <em>Finance and Stochastics</em>, 2002；对偶见 Andersen and Broadie, <em>Management Science</em>, 2004。</li></ul>',8))])}const f=i(m,[["render",c]]);export{A as __pageData,f as default};
